<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { LayoutDashboard, Package, Image, MousePointer2, GitBranch, ShoppingBag, Plus, Pencil, Trash2, X, Upload, Download, Printer, CheckCircle2, ArrowUpRight, Eye, ExternalLink, MapPinned, ChevronRight, ChevronDown, CircleAlert, Ticket, Search, Tags, Copy, Check, Layers, ArrowLeft, Megaphone, BarChart3 } from 'lucide-vue-next'
import { products, type Product, type ProductVariant, money } from '../data/products'
import { analyticsEvents, orders, storefront, metricSummary, storageIssue, createProduct, deleteProduct, downloadOrdersCsv, resetDemoData, updateOrderStatus, updateProduct, coupons, createCoupon, deleteCoupon, collections, saveCollection, deleteCollection, type Collection, type Coupon, type Order } from '../admin-store'

type Tab = 'Visão geral' | 'Produtos' | 'Ordens' | 'Coleções' | 'Tags' | 'Capas' | 'Mapa de cliques' | 'Funil' | 'Cupons' | 'Campanhas' | 'Acessos' | 'Número de vendas' | 'Usuários / Idade'
const tab = ref<Tab>('Visão geral')
const menuGroups: Array<{ key: string; label: string; icon: typeof LayoutDashboard; target?: Tab; children: Array<{ label: string; tab: Tab }> }> = [
  { key: 'orders', label: 'Orders', icon: ShoppingBag, target: 'Ordens', children: [{ label: 'Ordem de vendas', tab: 'Ordens' }] },
  { key: 'products', label: 'Produtos', icon: Package, target: 'Produtos', children: [{ label: 'Coleções', tab: 'Coleções' }, { label: 'Tags', tab: 'Tags' }] },
  { key: 'marketing', label: 'Marketing', icon: Megaphone, children: [{ label: 'Cupons', tab: 'Cupons' }, { label: 'Funil', tab: 'Funil' }, { label: 'Campanhas', tab: 'Campanhas' }] },
  { key: 'creative', label: 'Criativos', icon: Image, target: 'Capas', children: [{ label: 'Capas', tab: 'Capas' }] },
  { key: 'analytics', label: 'Analytics', icon: BarChart3, children: [{ label: 'Acessos', tab: 'Acessos' }, { label: 'Cliques', tab: 'Mapa de cliques' }, { label: 'Número de vendas', tab: 'Número de vendas' }, { label: 'Usuários / Idade', tab: 'Usuários / Idade' }] },
]
const expandedGroups = reactive<Record<string, boolean>>({ orders: false, products: false, marketing: false, creative: false, analytics: false })
const pageTitle = computed(() => tab.value === 'Ordens' ? 'Ordem de vendas' : tab.value === 'Mapa de cliques' ? 'Cliques' : tab.value)
const editing = ref<number | null>(null)
const selectedOrderId = ref<string>('')
const uploadError = ref('')
const productEditorOpen = ref(false)
const collectionEditorOpen = ref(false)
const editingCollectionId = ref<string | null>(null)
const collectionSearch = ref('')
const collectionDraft = reactive<Omit<Collection, 'id'>>({ name: '', description: '', active: true, productIds: [] })
const productSearch = ref('')
const productStatus = ref<'all' | 'active' | 'inactive'>('all')
const selectedProductIds = ref<number[]>([])
const couponDraft = reactive<Omit<Coupon, 'id' | 'used'>>({ code: '', type: 'percentage', value: 10, minimumOrder: 0, usageLimit: null, active: true })
const draft = reactive<Omit<Product, 'id'>>({ name: '', price: 0, category: 'Camisas', sizes: ['P', 'M', 'G', 'GG'], image: '/products/aegon-polo-on-model.png', images: ['/products/aegon-polo-on-model.png'], description: '', specs: [''], color: '#0045BA', colorName: 'Azul System Wake', badge: '', active: true, sku: '', stock: 0, tags: [], variants: [] })
const selectedOrder = computed(() => orders.find(order => order.id === selectedOrderId.value) || orders[0])
const heatPoints = computed(() => analyticsEvents.filter(event => event.name === 'product_click' && typeof event.x === 'number' && typeof event.y === 'number').slice(-35))
const funnel = computed(() => [
  { label: 'Passou o mouse', value: metricSummary.value.hovers, color: '#7CB9F2' },
  { label: 'Clicou no produto', value: metricSummary.value.clicks, color: '#0045BA' },
  { label: 'Adicionou à sacola', value: metricSummary.value.carts, color: '#FFC126' },
  { label: 'Iniciou checkout', value: metricSummary.value.checkouts, color: '#FF8100' },
  { label: 'Ordem concluída', value: metricSummary.value.sold, color: '#047857' },
])
const funnelMax = computed(() => Math.max(1, ...funnel.value.map(step => step.value)))
const filteredProducts = computed(() => {
  const query = productSearch.value.trim().toLocaleLowerCase('pt-BR')
  return products.filter(product => (productStatus.value === 'all' || (productStatus.value === 'active' ? product.active !== false : product.active === false)) && (!query || [product.name, product.sku, product.category, ...(product.tags || [])].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR').includes(query)))
})
const productTags = computed(() => {
  const counts = new Map<string, number>()
  products.forEach(product => new Set((product.tags || []).map(tag => tag.trim()).filter(Boolean)).forEach(tag => counts.set(tag, (counts.get(tag) || 0) + 1)))
  return [...counts].map(([name, count]) => ({ name, count })).sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'))
})
const allVisibleSelected = computed(() => !!filteredProducts.value.length && filteredProducts.value.every(product => selectedProductIds.value.includes(product.id)))
function selectTab(next: Tab) { tab.value = next; productEditorOpen.value = false; collectionEditorOpen.value = false }
function toggleGroup(group: typeof menuGroups[number]) { expandedGroups[group.key] = !expandedGroups[group.key]; if (group.target) selectTab(group.target) }
function showTaggedProducts(tag: string) { productSearch.value = tag; productStatus.value = 'all'; expandedGroups.products = true; selectTab('Produtos') }
function resetDraft(product?: Product) {
  productEditorOpen.value = true
  editing.value = product?.id ?? null
  Object.assign(draft, product ? { ...product, sizes: [...product.sizes], specs: [...product.specs], tags: [...(product.tags || [])], variants: (product.variants?.length ? product.variants : product.sizes.map((size, index) => ({ id: `${product.id}-${index}`, size, sku: `${product.sku || 'AEG'}-${size}`, stock: 0 }))).map(variant => ({ ...variant })), images: [...(product.images?.length ? product.images : [product.image])] } : { name: '', price: 0, category: 'Camisas', sizes: ['P', 'M', 'G', 'GG'], image: '/products/aegon-polo-on-model.png', images: ['/products/aegon-polo-on-model.png'], description: '', specs: [''], color: '#0045BA', colorName: 'Azul System Wake', badge: '', active: true, sku: '', stock: 0, tags: [], variants: [] })
  uploadError.value = ''
}
function saveProduct() {
  const variants = (draft.variants || []).filter(variant => variant.size.trim()).map(variant => ({ ...variant, size: variant.size.trim(), sku: variant.sku.trim(), stock: Math.max(0, Number(variant.stock) || 0) }))
  const product = { ...draft, name: draft.name.trim(), price: Number(draft.price), sku: draft.sku?.trim() || undefined, stock: Math.max(0, Number(draft.stock) || variants.reduce((total, variant) => total + variant.stock, 0)), tags: (draft.tags || []).map(tag => tag.trim()).filter(Boolean), sizes: (variants.length ? variants.map(variant => variant.size) : draft.sizes).filter(Boolean), variants, specs: draft.specs.filter(Boolean), images: draft.images?.filter(Boolean) || [], image: draft.images?.[0] || draft.image, description: draft.description.trim(), badge: draft.badge?.trim() || undefined }
  if (!product.name || !product.description || !product.sizes.length || product.price < 0) return
  if (editing.value) updateProduct(editing.value, product)
  else createProduct(product)
  editing.value = null
  productEditorOpen.value = false
}
function openCollection(collection?: Collection) {
  editingCollectionId.value = collection?.id ?? null
  Object.assign(collectionDraft, collection ? { name: collection.name, description: collection.description, active: collection.active, productIds: [...collection.productIds] } : { name: '', description: '', active: true, productIds: [] })
  collectionSearch.value = ''
  collectionEditorOpen.value = true
}
function submitCollection() {
  const name = collectionDraft.name.trim()
  if (!name) return
  saveCollection({ ...collectionDraft, name, description: collectionDraft.description.trim() }, editingCollectionId.value ?? undefined)
  collectionEditorOpen.value = false
}
function removeCollection(collection: Collection) {
  if (window.confirm(`Excluir a coleção “${collection.name}”?`)) deleteCollection(collection.id)
}
function removeProduct(product: Product) {
  if (window.confirm(`Remover “${product.name}” do catálogo? Esta ação só poderá ser desfeita ao restaurar os dados do navegador.`)) deleteProduct(product.id)
}
function updateFiles(event: Event) {
  const files = Array.from((event.target as HTMLInputElement).files || [])
  if (!files.length) return
  uploadError.value = ''
  if (files.some(file => !file.type.startsWith('image/') || file.size > 2_000_000)) { uploadError.value = 'Use imagens de até 2 MB em JPG, PNG, WebP ou SVG.'; return }
  Promise.all(files.map(file => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file) }))).then(images => { draft.images = [...(draft.images || []), ...images]; draft.image = draft.images[0] || draft.image }).catch(() => { uploadError.value = 'Não foi possível ler a imagem selecionada.' })
}
function removeImage(index: number) { draft.images?.splice(index, 1); draft.image = draft.images?.[0] || '/products/aegon-polo-on-model.png' }
function printLabel() { window.print() }
function setSizes(value: string) {
  const sizes = value.split(',').map(size => size.trim()).filter(Boolean)
  const old = draft.variants || []
  draft.sizes = sizes
  draft.variants = sizes.map((size, index) => old.find(variant => variant.size === size) || ({ id: crypto.randomUUID?.() || `${Date.now()}-${index}`, size, sku: `${draft.sku || 'AEG'}-${size}`, stock: 0 }))
}
function addVariant() { draft.variants = [...(draft.variants || []), { id: crypto.randomUUID?.() || `${Date.now()}-${draft.variants?.length || 0}`, size: '', sku: draft.sku || '', stock: 0 }] }
function removeVariant(index: number) { draft.variants?.splice(index, 1); draft.sizes = (draft.variants || []).map(variant => variant.size).filter(Boolean) }
function syncVariants() { draft.sizes = (draft.variants || []).map(variant => variant.size.trim()).filter(Boolean) }
function toggleVisibleProducts() { selectedProductIds.value = allVisibleSelected.value ? selectedProductIds.value.filter(id => !filteredProducts.value.some(product => product.id === id)) : [...new Set([...selectedProductIds.value, ...filteredProducts.value.map(product => product.id)])] }
function setSelectedProductsActive(active: boolean) { products.filter(product => selectedProductIds.value.includes(product.id)).forEach(product => { product.active = active }); selectedProductIds.value = [] }
function saveCoupon() { if (!couponDraft.code.trim() || (couponDraft.type !== 'shipping' && Number(couponDraft.value) <= 0)) return; createCoupon({ ...couponDraft, code: couponDraft.code.trim(), value: Number(couponDraft.value) || 0, minimumOrder: Number(couponDraft.minimumOrder) || 0, usageLimit: couponDraft.usageLimit ? Number(couponDraft.usageLimit) : null }); Object.assign(couponDraft, { code: '', type: 'percentage', value: 10, minimumOrder: 0, usageLimit: null, active: true }) }
function copyCoupon(code: string) { navigator.clipboard?.writeText(code) }
</script>

<template>
  <div class="admin-shell">
    <aside class="admin-sidebar">
      <RouterLink to="/" class="admin-logo" aria-label="Voltar para a loja"><img src="/brand/assets/Logos/aegon-logo-escuro.svg" alt="aegon" /><span>admin</span></RouterLink>
      <nav class="admin-navigation" aria-label="Navegação administrativa">
        <button class="nav-home" :class="{ selected: tab === 'Visão geral' }" :aria-current="tab === 'Visão geral' ? 'page' : undefined" @click="selectTab('Visão geral')"><LayoutDashboard :size="18" />Visão geral</button>
        <div v-for="group in menuGroups" :key="group.key" class="nav-group">
          <button class="nav-master" :class="{ 'group-active': group.target === tab || group.children.some(child => child.tab === tab) }" :aria-expanded="!!expandedGroups[group.key]" :aria-controls="'admin-menu-' + group.key" @click="toggleGroup(group)"><component :is="group.icon" :size="18" /><span>{{ group.label }}</span><ChevronDown :size="15" class="nav-chevron" :class="{ collapsed: !expandedGroups[group.key] }" /></button>
          <div v-show="expandedGroups[group.key]" :id="'admin-menu-' + group.key" class="nav-children"><button v-for="child in group.children" :key="child.tab" :class="{ selected: tab === child.tab }" :aria-current="tab === child.tab ? 'page' : undefined" @click="selectTab(child.tab)">{{ child.label }}</button></div>
        </div>
      </nav>
      <div class="admin-sidebar-bottom"><RouterLink to="/" target="_blank"><ExternalLink :size="16" />Ver loja</RouterLink><span>Modo local · v0.1</span></div>
    </aside>
    <main class="admin-main">
      <header class="admin-topbar"><div><span class="eyebrow">AEGON STORE / OPERAÇÃO</span><h1>{{ pageTitle }}</h1></div><div class="admin-topbar-actions"><span class="admin-live"><i></i> Dados deste navegador</span><RouterLink to="/" class="button button-outline">Ver loja <ArrowUpRight :size="16" /></RouterLink></div></header>
      <p v-if="storageIssue" class="admin-alert"><CircleAlert :size="18" />{{ storageIssue }}</p>

      <section v-if="tab === 'Visão geral'" class="admin-view">
        <div class="admin-welcome"><div><span class="eyebrow">PAINEL DE OPERAÇÃO</span><h2>Uma visão clara do que está <span>on</span>.</h2><p>Leituras de navegação, pedidos de demonstração e atalhos da sua loja.</p></div><button class="button button-primary" @click="tab = 'Produtos'; resetDraft()"><Plus :size="17" />Novo produto</button></div>
        <div class="metric-grid"><article><span>Ordens concluídas</span><strong>{{ metricSummary.sold }}</strong><small>nesta instalação</small></article><article><span>Receita simulada</span><strong>{{ money(metricSummary.revenue) }}</strong><small>sem processamento financeiro</small></article><article><span>Adições à sacola</span><strong>{{ metricSummary.carts }}</strong><small>{{ metricSummary.clicks ? `${Math.round(metricSummary.carts / metricSummary.clicks * 100)}% dos cliques` : 'aguardando navegação' }}</small></article><article><span>Conversão</span><strong>{{ metricSummary.conversion.toFixed(1).replace('.', ',') }}%</strong><small>pedido / clique no produto</small></article></div>
        <div class="admin-split"><section class="admin-panel"><div class="admin-panel-title"><div><span class="eyebrow">PRÓXIMA AÇÃO</span><h3>Ordens recentes</h3></div><button class="text-link" @click="tab = 'Ordens'">Ver todos <ChevronRight :size="16" /></button></div><div v-if="orders.length" class="admin-order-list"><button v-for="order in orders.slice(0, 4)" :key="order.id" @click="tab = 'Ordens'; selectedOrderId = order.id"><span><strong>{{ order.id }}</strong><small>{{ order.customer.name }} · {{ new Date(order.createdAt).toLocaleDateString('pt-BR') }}</small></span><span><em :class="`status-${order.status.toLowerCase()}`">{{ order.status }}</em><strong>{{ money(order.total) }}</strong></span></button></div><div v-else class="admin-empty"><ShoppingBag :size="28" /><p>Ainda não há pedidos por aqui.</p><small>Conclua a simulação de checkout na loja e ele aparecerá aqui.</small></div></section>
          <section class="admin-panel"><div class="admin-panel-title"><div><span class="eyebrow">FILA DA LOJA</span><h3>Funil agora</h3></div><button class="text-link" @click="tab = 'Funil'">Abrir funil <ChevronRight :size="16" /></button></div><div class="mini-funnel"><div v-for="step in funnel" :key="step.label"><span>{{ step.label }}</span><b><i :style="{ width: `${step.value / funnelMax * 100}%`, background: step.color }"></i></b><strong>{{ step.value }}</strong></div></div></section></div>
        <section class="admin-panel quick-actions"><div><span class="eyebrow">ATALHOS</span><h3>O que você quer ajustar?</h3></div><button @click="tab = 'Capas'"><Image :size="22" />Capas da loja <ArrowUpRight :size="16" /></button><button @click="tab = 'Mapa de cliques'"><MapPinned :size="22" />Mapa de cliques <ArrowUpRight :size="16" /></button><button @click="tab = 'Produtos'; resetDraft()"><Package :size="22" />Criar produto <ArrowUpRight :size="16" /></button></section>
      </section>

      <section v-else-if="tab === 'Produtos'" class="admin-view">
        <template v-if="!productEditorOpen">
          <div class="admin-section-head"><div><p>Organize seu catálogo e acompanhe o status, os preços e o estoque.</p></div><button class="button button-primary" @click="resetDraft()"><Plus :size="17" />Adicionar produto</button></div>
          <div class="catalog-summary"><div><span>Todos os produtos</span><strong>{{ products.length }}</strong></div><div><span>Publicados</span><strong>{{ products.filter(product => product.active !== false).length }}</strong></div><div><span>Ocultos</span><strong>{{ products.filter(product => product.active === false).length }}</strong></div></div>
          <section class="admin-panel catalog-table-panel">
            <div class="catalog-tabs" aria-label="Status do produto"><button v-for="option in [{ value: 'all', label: 'Todos' }, { value: 'active', label: 'Publicados' }, { value: 'inactive', label: 'Ocultos' }] as const" :key="option.value" :class="{ active: productStatus === option.value }" @click="productStatus = option.value">{{ option.label }}</button></div>
            <div class="catalog-controls"><div class="admin-search"><Search :size="16" /><input v-model="productSearch" aria-label="Buscar produtos" placeholder="Buscar por produto, SKU ou tag" /></div><span>{{ filteredProducts.length }} produto{{ filteredProducts.length === 1 ? '' : 's' }}</span></div>
            <div v-if="selectedProductIds.length" class="admin-bulk-bar"><strong>{{ selectedProductIds.length }} selecionado(s)</strong><button @click="setSelectedProductsActive(true)">Publicar</button><button @click="setSelectedProductsActive(false)">Ocultar</button><button class="text-link" @click="selectedProductIds = []">Limpar seleção</button></div>
            <div class="catalog-table-scroll"><table class="catalog-table"><thead><tr><th><input :checked="allVisibleSelected" type="checkbox" aria-label="Selecionar todos os produtos visíveis" @change="toggleVisibleProducts" /></th><th>Produto</th><th>Status</th><th>Estoque</th><th>Categoria</th><th>Preço</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>
              <tr v-for="product in filteredProducts" :key="product.id"><td><input v-model="selectedProductIds" type="checkbox" :value="product.id" :aria-label="'Selecionar ' + product.name" /></td><td><button class="catalog-product-link" @click="resetDraft(product)"><img :src="product.image" :alt="product.name" /><span><strong>{{ product.name }}</strong><small>{{ product.sku || 'Sem SKU' }}</small></span></button></td><td><span class="admin-status" :class="{ muted: product.active === false }">{{ product.active === false ? 'Oculto' : 'Publicado' }}</span></td><td>{{ product.stock ?? 0 }} em estoque <small v-if="product.variants?.length">· {{ product.variants.length }} variações</small></td><td>{{ product.category }}</td><td>{{ money(product.price) }}</td><td><div class="catalog-row-actions"><button class="icon-button" :aria-label="'Editar ' + product.name" @click="resetDraft(product)"><Pencil :size="16" /></button><button class="icon-button danger" :aria-label="'Remover ' + product.name" @click="removeProduct(product)"><Trash2 :size="16" /></button></div></td></tr>
              <tr v-if="!filteredProducts.length"><td colspan="7" class="catalog-no-results">Nenhum produto encontrado com estes filtros.</td></tr>
            </tbody></table></div>
          </section>
        </template>
        <template v-else>
          <div class="editor-heading"><button class="editor-back" type="button" @click="productEditorOpen = false"><ArrowLeft :size="17" /> Produtos</button><div><span class="eyebrow">{{ editing ? 'EDIÇÃO DO PRODUTO' : 'NOVO PRODUTO' }}</span><h2>{{ editing ? (draft.name || 'Editar produto') : 'Adicionar produto' }}</h2></div></div>
          <div class="product-editor-page">
          <form class="admin-panel product-editor" @submit.prevent="saveProduct">
            <div class="admin-panel-title"><div><span class="eyebrow">{{ editing ? 'EDITAR PRODUTO' : 'NOVO PRODUTO' }}</span><h3>{{ editing ? 'Ajuste o essencial.' : 'Crie um essencial.' }}</h3></div><button type="button" class="icon-button" aria-label="Fechar edição" @click="productEditorOpen = false"><X :size="18" /></button></div>
            <div class="admin-form-grid">
              <label class="admin-form-span">Nome<input v-model.trim="draft.name" required maxlength="100" placeholder="Ex.: Polo Aegon System Wake" /></label>
              <label>Preço (R$)<input v-model.number="draft.price" required min="0" step="0.01" type="number" /></label><label>Categoria<select v-model="draft.category"><option>Camisas</option><option>Garrafas</option><option>Cadernos</option><option>Combos</option></select></label>
              <label>SKU principal<input v-model.trim="draft.sku" placeholder="AEG-POLO-001" /></label><label>Estoque total<input v-model.number="draft.stock" min="0" type="number" /></label>
              <label class="admin-form-span">Tags <small>Separe por vírgula</small><input :value="(draft.tags || []).join(', ')" @input="draft.tags = ($event.target as HTMLInputElement).value.split(',').map(tag => tag.trim())" placeholder="Novo, Uniforme, Coleção 01" /></label>
              <label>Cor<input v-model.trim="draft.colorName" required placeholder="Azul System Wake" /></label><label>Hex<input v-model="draft.color" required pattern="#[0-9a-fA-F]{6}" placeholder="#0045BA" /></label>
              <label class="admin-form-span">Tamanhos / opções <small>Ao editar, as variações abaixo acompanham.</small><input :value="draft.sizes.join(', ')" @input="setSizes(($event.target as HTMLInputElement).value)" placeholder="P, M, G, GG" /></label>
              <div class="admin-form-span variant-editor"><div><span><Tags :size="15" />Variações de tamanho</span><button type="button" class="text-link" @click="addVariant"><Plus :size="14" />Adicionar variação</button></div><section v-for="(variant, index) in draft.variants" :key="variant.id" class="variant-row"><input v-model.trim="variant.size" required placeholder="Tamanho" @change="syncVariants" /><input v-model.trim="variant.sku" placeholder="SKU da variação" /><input v-model.number="variant.stock" min="0" type="number" placeholder="Estoque" /><button type="button" class="icon-button danger" :aria-label="`Remover variação ${index + 1}`" @click="removeVariant(index)"><Trash2 :size="15" /></button></section><small v-if="!draft.variants?.length">Adicione tamanhos para controlar SKU e estoque por variação.</small></div>
              <label class="admin-form-span">Descrição<textarea v-model.trim="draft.description" required rows="3" placeholder="Conte a história deste essencial."></textarea></label><label class="admin-form-span">Detalhes <small>Um por linha</small><textarea :value="draft.specs.join('\n')" rows="4" @input="draft.specs = ($event.target as HTMLTextAreaElement).value.split('\n')" placeholder="Material\nAcabamento\nCuidados"></textarea></label><label class="admin-form-span">Selo opcional<input v-model.trim="draft.badge" placeholder="Ex.: Novo por aqui" /></label><label class="admin-check"><input v-model="draft.active" type="checkbox" />Publicar agora</label>
            </div>
            <div class="admin-media"><span>Fotos do produto</span><div class="admin-image-list"><div v-for="(image, index) in draft.images" :key="image" class="admin-image-thumb"><img :src="image" alt="Prévia" /><button type="button" :aria-label="`Remover foto ${index + 1}`" @click="removeImage(index)"><X :size="14" /></button></div><label class="admin-upload"><Upload :size="20" /><span>Adicionar fotos</span><input accept="image/png,image/jpeg,image/webp,image/svg+xml" multiple type="file" @change="updateFiles" /></label></div><small v-if="uploadError" class="field-error">{{ uploadError }}</small><small>JPG, PNG, WebP ou SVG, até 2 MB por foto. A primeira será a capa.</small></div><button class="button button-primary full-width" type="submit"><CheckCircle2 :size="17" />{{ editing ? 'Salvar alterações' : 'Criar produto' }}</button>
          </form>
          </div>
        </template>
      </section>

      <section v-else-if="tab === 'Coleções'" class="admin-view">
        <template v-if="!collectionEditorOpen">
          <div class="admin-section-head"><p>Reúna produtos em coleções para organizar o catálogo.</p><button class="button button-primary" @click="openCollection()"><Plus :size="17" />Criar coleção</button></div>
          <section class="admin-panel catalog-table-panel">
            <div class="catalog-controls"><div class="admin-search"><Search :size="16" /><input v-model="collectionSearch" aria-label="Buscar coleções" placeholder="Buscar coleção" /></div><span>{{ collections.length }} coleções</span></div>
            <div class="catalog-table-scroll"><table class="catalog-table"><thead><tr><th>Coleção</th><th>Status</th><th>Produtos</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>
              <tr v-for="collection in collections.filter(item => item.name.toLocaleLowerCase('pt-BR').includes(collectionSearch.trim().toLocaleLowerCase('pt-BR')))" :key="collection.id"><td><button class="collection-link" @click="openCollection(collection)"><strong>{{ collection.name }}</strong><small>{{ collection.description || 'Sem descrição' }}</small></button></td><td><span class="admin-status" :class="{ muted: !collection.active }">{{ collection.active ? 'Ativa' : 'Oculta' }}</span></td><td>{{ collection.productIds.filter(id => products.some(product => product.id === id)).length }}</td><td><div class="catalog-row-actions"><button class="icon-button" :aria-label="'Editar ' + collection.name" @click="openCollection(collection)"><Pencil :size="16" /></button><button class="icon-button danger" :aria-label="'Excluir ' + collection.name" @click="removeCollection(collection)"><Trash2 :size="16" /></button></div></td></tr>
