          <div class="editor-heading"><button class="editor-back" type="button" @click="collectionEditorOpen = false"><ArrowLeft :size="17" /> Coleções</button><div><span class="eyebrow">{{ editingCollectionId ? 'EDITAR COLEÇÃO' : 'NOVA COLEÇÃO' }}</span><h2>{{ editingCollectionId ? (collectionDraft.name || 'Editar coleção') : 'Criar coleção' }}</h2></div></div>
          <form class="admin-panel collection-editor" @submit.prevent="submitCollection">
            <div class="admin-form-grid"><label class="admin-form-span">Nome da coleção<input v-model.trim="collectionDraft.name" required maxlength="100" placeholder="Ex.: Aegon Essentials" /></label><label class="admin-form-span">Descrição<textarea v-model.trim="collectionDraft.description" rows="4" maxlength="500" placeholder="Conte o que reúne estes produtos."></textarea></label><label class="admin-check"><input v-model="collectionDraft.active" type="checkbox" />Coleção ativa</label></div>
            <div class="collection-products"><div class="admin-panel-title"><div><span class="eyebrow">CATÁLOGO</span><h3>Produtos da coleção</h3></div><strong>{{ collectionDraft.productIds.length }} selecionado(s)</strong></div><div class="admin-search"><Search :size="16" /><input v-model="collectionSearch" aria-label="Buscar produtos para a coleção" placeholder="Buscar produtos" /></div><div class="collection-product-list"><label v-for="product in products.filter(item => item.name.toLocaleLowerCase('pt-BR').includes(collectionSearch.trim().toLocaleLowerCase('pt-BR')))" :key="product.id"><input v-model="collectionDraft.productIds" type="checkbox" :value="product.id" /><img :src="product.image" :alt="product.name" /><span><strong>{{ product.name }}</strong><small>{{ product.category }} · {{ money(product.price) }}</small></span></label></div></div>
            <div class="editor-actions"><button type="button" class="button button-outline" @click="collectionEditorOpen = false">Cancelar</button><button type="submit" class="button button-primary"><CheckCircle2 :size="17" />Salvar coleção</button></div>
