><small>{{ coupon.minimumOrder ? `Pedidos a partir de ${money(coupon.minimumOrder)}` : 'Sem pedido mínimo' }} · {{ coupon.used }}{{ coupon.usageLimit ? ` / ${coupon.usageLimit}` : '' }} usos</small><footer><label class="coupon-active"><input v-model="coupon.active" type="checkbox" /><span>{{ coupon.active ? 'Ativo' : 'Pausado' }}</span></label><button class="icon-button danger" :aria-label="`Excluir cupom ${coupon.code}`" @click="deleteCoupon(coupon.id)"><Trash2 :size="16" /></button></footer></article></div><div v-else class="admin-empty"><Ticket :size="28" /><p>Nenhum cupom criado ainda.</p></div></section></div>
